static int iguanair_suspend ( struct usb_interface * intf , pm_message_t message ) { struct iguanair * ir = usb_get_intfdata ( intf ) ; int rc = 0 ; mutex_lock ( & ir -> lock ) ; if ( ir -> receiver_on ) { rc = iguanair_receiver ( ir , false ) ; if ( rc ) { dev_warn ( ir -> dev , "failed to disable receiver for suspend\n" ) ; } } usb_kill_urb ( ir -> urb_in , NULL ) ; usb_kill_urb ( ir -> urb_out ) ; mutex_unlock ( & ir -> lock ) ; return rc ; } 